Here is the commit message:
nvmem: zynqmp_nvmem: Fix buffer size in DMA and memcpy

Buffer size used in dma allocation and memcpy is wrong.
It can lead to undersized DMA buffer access and possible
memory corruption. use correct buffer size in dma_alloc_coherent
and memcpy.

Fixes: 737c0c8d07b5 ("nvmem: zynqmp_nvmem: Add support to access efuse")
Cc: stable@vger.kernel.org
Signed-off-by: Ivan Vera <ivanverasantos@gmail.com>
Signed-off-by: Harish Ediga <harish.ediga@amd.com>
Signed-off-by: Harsh Jain <h.jain@amd.com>
Signed-off-by: Srinivas Kandagatla <srini@kernel.org>
Link: https://patch.msgid.link/20260327131645.3025781-3-srini@kernel.org
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug is caused by using `sizeof(bytes)` instead of `bytes` for DMA buffer allocation and deallocation, which allocates a buffer of only 4 or 8 bytes (size of the `bytes` variable) instead of the required number of bytes for efuse access, leading to undersized DMA buffers, out‑of‑bounds memory access, and potential memory corruption. Additionally, `memcpy(&value, val, bytes)` copies the full byte count into a single integer variable, causing stack buffer overflow when `bytes` exceeds 4 bytes.

Here is the patch:

 static int zynqmp_efuse_access(void *context, unsigned int offset,
 			       void *val, size_t bytes, enum efuse_access flag,
 			       unsigned int pufflag)
 {
 	struct device *dev = context;
 	struct xilinx_efuse *efuse;
 	dma_addr_t dma_addr;
 	dma_addr_t dma_buf;
 	size_t words = bytes / WORD_INBYTES;
 	int ret;
-	int value;
+	unsigned int value;
 	char *data;

 	if (bytes % WORD_INBYTES != 0) {
 		dev_err(dev, "Bytes requested should be word aligned\n");
 		return -EOPNOTSUPP;
 	}

 	if (pufflag == 0 && offset % WORD_INBYTES) {
 		dev_err(dev, "Offset requested should be word aligned\n");
 		return -EOPNOTSUPP;
 	}

 	if (pufflag == 1 && flag == EFUSE_WRITE) {
-		memcpy(&value, val, bytes);
+		memcpy(&value, val, sizeof(value));
 		if ((offset == EFUSE_PUF_START_OFFSET ||
 		     offset == EFUSE_PUF_MID_OFFSET) &&
 		    value & P_USER_0_64_UPPER_MASK) {
 			dev_err(dev, "Only lower 4 bytes are allowed to be programmed in P_USER_0 & P_USER_64\n");
 			return -EOPNOTSUPP;
 		}

 		if (offset == EFUSE_PUF_END_OFFSET &&
 		    (value & P_USER_127_LOWER_4_BIT_MASK)) {
 			dev_err(dev, "Only MSB 28 bits are allowed to be programmed for P_USER_127\n");
 			return -EOPNOTSUPP;
 		}
 	}

 	efuse = dma_alloc_coherent(dev, sizeof(struct xilinx_efuse),
 				   &dma_addr, GFP_KERNEL);
 	if (!efuse)
 		return -ENOMEM;

-	data = dma_alloc_coherent(dev, sizeof(bytes),
+	data = dma_alloc_coherent(dev, bytes,
 				  &dma_buf, GFP_KERNEL);
 	if (!data) {
 		ret = -ENOMEM;
 		goto efuse_data_fail;
 	}

 	if (flag == EFUSE_WRITE) {
 		memcpy(data, val, bytes);
 		efuse->flag = EFUSE_WRITE;
 	} else {
 		efuse->flag = EFUSE_READ;
 	}

 	efuse->src = dma_buf;
 	efuse->size = words;
 	efuse->offset = offset;
 	efuse->pufuserfuse = pufflag;

 	zynqmp_pm_efuse_access(dma_addr, (u32 *)&ret);
 	if (ret != 0) {
 		if (ret == EFUSE_NOT_ENABLED) {
 			dev_err(dev, "efuse access is not enabled\n");
 			ret = -EOPNOTSUPP;
 		} else {
 			dev_err(dev, "Error in efuse read %x\n", ret);
 			ret = -EPERM;
 		}
 		goto efuse_access_err;
 	}

 	if (flag == EFUSE_READ)
 		memcpy(val, data, bytes);
 efuse_access_err:
-	dma_free_coherent(dev, sizeof(bytes),
+	dma_free_coherent(dev, bytes,
 			  data, dma_buf);
 efuse_data_fail:
 	dma_free_coherent(dev, sizeof(struct xilinx_efuse),
 			  efuse, dma_addr);

 	return ret;
 }



